 * SQL statement splitting for the JavaScript bindings.
 *
 * Splits a SQL string into individual statements so each can be prepared or
 * executed on its own. A naive split on `;` is incorrect for trigger bodies:
 * a `CREATE TRIGGER ... BEGIN ...; ...; END;` definition contains its own
 * semicolon-terminated sub-statements that must stay together. This splitter
 * recognizes trigger definitions and keeps their whole `BEGIN ... END` body as
 * a single statement.
 *
 * Recognized trigger forms:
 *   - CREATE TRIGGER ...
 *   - CREATE TEMP TRIGGER ... (also TEMPORARY)
 *   - EXPLAIN CREATE TRIGGER ... (also EXPLAIN QUERY PLAN CREATE TRIGGER ...)
 *
 * Only a bare `END` outside of string literals terminates a trigger body; an
 * `END` appearing inside a quoted string is ignored. `CASE ... END` and any
 * other `BEGIN ... END` nesting inside the body is tracked with a depth counter
 * so the body is only closed by its matching `END`.
 */

/**
 * Split SQL text into an array of individual statement strings.
 *
 * Each returned statement has its surrounding whitespace trimmed, while all
 * internal whitespace (newlines, indentation, spacing within the body) is
 * preserved exactly. Trigger definitions are returned as a single element
 * regardless of how many semicolon-terminated statements appear in their body.
 *
 * @param {string} sql - The SQL text to split.
 * @returns {string[]} The individual statements, in order, empties omitted.
 */
export function splitStatements(sql) {
    const statements = [];
    const n = sql.length;

    // Index in `sql` where the current statement begins.
    let start = 0;

    // Lowercased bare-word tokens seen so far in the current statement. Used to
    // detect a trigger header and to track BEGIN/CASE ... END nesting.
    let words = [];
    let isTrigger = false;   // current statement is a trigger definition
    let bodyStarted = false; // the trigger's BEGIN has been seen
    let depth = 0;           // BEGIN/CASE nesting depth inside the trigger body

    // Position of the start of a word currently being scanned, or -1 if none.
    let wordStart = -1;

    let i = 0;

    const isWordChar = (c) =>
        (c >= 'a' && c <= 'z') ||
        (c >= 'A' && c <= 'Z') ||
        (c >= '0' && c <= '9') ||
        c === '_';

    const pushStatement = (end) => {
        const text = sql.slice(start, end).trim();
        if (text) {
            statements.push(text);
        }
    };

    const resetStatement = (newStart) => {
        start = newStart;
        words = [];
        isTrigger = false;
        bodyStarted = false;
        depth = 0;
    };

    const onWord = (word) => {
        words.push(word);

        // Detect the trigger header the moment the `trigger` keyword lands in
        // the expected position: [EXPLAIN [QUERY PLAN]] CREATE [TEMP|TEMPORARY] TRIGGER
        if (!isTrigger && word === 'trigger') {
            let k = 0;
            if (words[k] === 'explain') {
                k++;
                if (words[k] === 'query' && words[k + 1] === 'plan') {
                    k += 2;
                }
            }
            if (words[k] === 'create') {
                k++;
                if (words[k] === 'temp' || words[k] === 'temporary') {
                    k++;
                }
                // `trigger` must be exactly the token we just appended.
                if (k === words.length - 1) {
                    isTrigger = true;
                }
            }
        }

        if (isTrigger) {
            if (word === 'begin') {
                depth++;
                bodyStarted = true;
            } else if (word === 'case') {
                depth++;
            } else if (word === 'end') {
                if (depth > 0) {
                    depth--;
                }
            }
        }
    };

    const flushWord = () => {
        if (wordStart >= 0) {
            onWord(sql.slice(wordStart, i).toLowerCase());
            wordStart = -1;
        }
    };

    while (i < n) {
        const char = sql[i];
        const nextChar = sql[i + 1];

        // String literal (single quote, double quote, or backtick). Consumed
        // whole so its contents are never treated as words or delimiters.
        if (char === "'" || char === '"' || char === '`') {
            flushWord();
            const quote = char;
            i++;
            while (i < n) {
                if (sql[i] === quote) {
                    if (sql[i + 1] === quote) {
                        // Escaped quote (doubled), stay in the string.
                        i += 2;
                        continue;
                    }
                    i++;
                    break;
                }
                i++;
            }
            continue;
        }

        // Single-line comment.
        if (char === '-' && nextChar === '-') {
            flushWord();
            i += 2;
            while (i < n && sql[i] !== '\n') {
                i++;
            }
            continue;
        }

        // Multi-line comment.
        if (char === '/' && nextChar === '*') {
            flushWord();
            i += 2;
            while (i < n && !(sql[i] === '*' && sql[i + 1] === '/')) {
                i++;
            }
            i += 2; // skip past the closing "*/"
            continue;
        }

        // Accumulate a bare word.
        if (isWordChar(char)) {
            if (wordStart < 0) {
                wordStart = i;
            }
            i++;
            continue;
        }

        // Any non-word character ends the current word.
        flushWord();

        if (char === ';') {
            // A semicolon terminates the statement unless we are inside a
            // trigger body that has not yet reached its matching END.
            const insideOpenTrigger =
                isTrigger && !(bodyStarted && depth === 0);
            if (!insideOpenTrigger) {
                pushStatement(i); // exclude the ';'
                i++;
                resetStatement(i);
                continue;
            }
        }

        i++;
    }

    // Emit any trailing statement (input not terminated by a semicolon).
    flushWord();
    pushStatement(n);

    return statements;
}
